fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Create a new vector with capacity equal to the original length
    let mut result = Vec::with_capacity(list.len());
    
    // Append elements from index n to the end
    result.extend_from_slice(&list[n..]);
    
    // Append elements from index 0 to n
    result.extend_from_slice(&list[0..n]);
    
    result
}